constexpr int compute(const int& val) { return val + 1; }

// Context 1: Compile-Time Evaluation (Reference target is constexpr)
constexpr int Base_CT = 10;
constexpr const int& Ref_CT = Base_CT;
constexpr int Result_CT = compute(Ref_CT); // Fully CT

// Context 2: Runtime Evaluation (Reference target is not constexpr)
int Base_RT = 20;
const int& Ref_RT = Base_RT;
// Result is computed at runtime, even though compute is constexpr
const int Result_RT = compute(Ref_RT);
// (Result_RT cannot be marked constexpr because Ref_RT is not)
